51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    /**
76	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
77	     * and a domain containing at least one dot, with no whitespace in any segment.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
83	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
84	     */
85	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
86	        "ST", "STREET",
87	        "RD", "ROAD",
88	        "AVE", "AVENUE");
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        validateRequiredFields(ownerFieldsDto);
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
132	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
133	            joinHousehold(owner);
134	        } else {
135	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
136	        }
137	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
138	        requireUniqueTelephone(telephone);
139	        owner.setTelephone(telephone);
140	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
141	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    /**
150	     * Generates the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}.
151	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN} is a
152	     * global, 4-digit zero-padded sequence equal to one more than the current number of owners
153	     * (e.g. {@code 'SMI-0007'}).
154	     *
155	     * @param lastName the owner's last name
156	     * @return the generated customer code
157	     */
158	    private String generateCustomerCode(String lastName) {
159	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
160	        int sequence = this.clinicService.findAllOwners().size() + 1;
161	        return String.format("%s-%04d", last3, sequence);
162	    }
163	
164	    /**
165	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
166	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
167	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
168	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
169	     *
170	     * @param ownerFieldsDto the submitted owner fields
171	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
172	     */
173	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
174	        List<String> invalidFields = new ArrayList<>();
175	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
176	            invalidFields.add("firstName");
177	        }
178	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
179	            invalidFields.add("lastName");
180	        }
181	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
182	            invalidFields.add("address");
183	        }
184	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
185	            invalidFields.add("city");
186	        }
187	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
188	            invalidFields.add("telephone");
189	        }
190	        if (!invalidFields.isEmpty()) {
191	            throw new InvalidOwnerFieldsException(invalidFields);
192	        }
193	    }
194	
195	    /**
196	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
197	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
198	     * what gets stored and returned.
199	     *
200	     * @param telephone the raw telephone value from the request
201	     * @return the normalized E.164 telephone number
202	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
203	     */
204	    private String normalizeTelephone(String telephone) {
205	        String e164 = toE164(telephone);
206	        if (e164 == null) {
207	            throw new InvalidOwnerFieldsException(List.of("telephone"));
208	        }
209	        return e164;
210	    }
211	
212	    /**
213	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
214	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
215	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
216	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
217	     * it contains 8 to 15 digits after the {@code '+'}.
218	     *
219	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
220	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
221	     *
222	     * @param telephone the raw telephone value, possibly {@code null}
223	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
224	     */
225	    private String toE164(String telephone) {
226	        if (telephone == null) {
227	            return null;
228	        }
229	        String cleaned = telephone.replaceAll("[ \\-()]", "");
230	        String digits;
231	        if (cleaned.startsWith("+")) {
232	            digits = cleaned.substring(1);
233	        } else {
234	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
235	            digits = "61" + national;
236	        }
237	        if (!digits.matches("[0-9]{8,15}")) {
238	            return null;
239	        }
240	        return "+" + digits;
241	    }
242	
243	    /**
244	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
245	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
246	     * and returned lower-cased.
247	     *
248	     * @param email the raw email value from the request, possibly {@code null}
249	     * @return the lower-cased email, or {@code null} when none was supplied
250	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
251	     */
252	    private String normalizeEmail(String email) {
253	        if (!StringUtils.hasText(email)) {
254	            return null;
255	        }
256	        String trimmed = email.trim();
257	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
258	            throw new InvalidOwnerFieldsException(List.of("email"));
259	        }
260	        return trimmed.toLowerCase(Locale.ROOT);
261	    }
262	
263	    /**
264	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
265	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
266	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
267	     *
268	     * @param telephone the normalized (E.164) telephone of the owner being created
269	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
270	     */
271	    private void requireUniqueTelephone(String telephone) {
272	        boolean inUse = this.clinicService.findAllOwners().stream()
273	            .map(Owner::getTelephone)
274	            .filter(existing -> existing != null)
275	            .map(existing -> {
276	                String e164 = toE164(existing);
277	                return e164 != null ? e164 : existing;
278	            })
279	            .anyMatch(telephone::equals);
280	        if (inUse) {
281	            throw new DuplicateTelephoneException(telephone);
282	        }
283	    }
284	
285	    /**
286	     * Rejects an owner whose last name and address match those of an existing owner, where both are
287	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
288	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
289	     *
290	     * @param lastName the last name of the owner being created
291	     * @param address the address of the owner being created
292	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
293	     */
294	    private void requireUniqueHousehold(String lastName, String address) {
295	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
296	            throw new DuplicateHouseholdException(lastName, address);
297	        }
298	    }
299	
300	    /**
301	     * Returns the existing owners that belong to the same household as the given last name and
302	     * address, i.e. those whose last name and address match case-insensitively and with runs of
303	     * whitespace collapsed to a single space.
304	     *
305	     * @param lastName the last name to match
306	     * @param address the address to match
307	     * @return the matching owners (possibly empty, never {@code null})
308	     */
309	    private List<Owner> findHouseholdMembers(String lastName, String address) {
310	        String normalizedLastName = normalizeForHousehold(lastName);
311	        String normalizedAddress = normalizeAddress(address);
312	        return this.clinicService.findAllOwners().stream()
313	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
314	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
315	            .toList();
316	    }
317	
318	    /**
319	     * Joins the owner being created to the shared household of any existing owner(s) that have the
320	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
321	     * member of the household - the existing owners and the new one - is assigned the same stable
322	     * {@code householdId}, so the shared identifier can be read back from any of them.
323	     *
324	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
325	     * the owner is left without a {@code householdId}.
326	     *
327	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
328	     */
329	    private void joinHousehold(Owner owner) {
330	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
331	        if (members.isEmpty()) {
332	            return;
333	        }
334	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
335	        owner.setHouseholdId(householdId);
336	        for (Owner member : members) {
337	            if (!householdId.equals(member.getHouseholdId())) {
338	                member.setHouseholdId(householdId);
339	                this.clinicService.saveOwner(member);
340	            }
341	        }
342	    }
343	
344	    /**
345	     * Computes the stable, shared household identifier for a last name and address. The value is
346	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
347	     * name and address, so every owner in the same household computes the same identifier.
348	     *
349	     * @param lastName the last name of the household
350	     * @param address the address of the household
351	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
352	     */
353	    private String computeHouseholdId(String lastName, String address) {
354	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
355	        try {
356	            byte[] digest = MessageDigest.getInstance("SHA-256")
357	                .digest(key.getBytes(StandardCharsets.UTF_8));
358	            StringBuilder hex = new StringBuilder();
359	            for (int i = 0; i < 6; i++) {
360	                hex.append(String.format("%02X", digest[i]));
361	            }
362	            return "HH-" + hex;
363	        } catch (NoSuchAlgorithmException e) {
364	            throw new IllegalStateException("SHA-256 algorithm not available", e);
365	        }
366	    }
367	
368	    /**
369	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
370	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
371	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
372	     *
373	     * @param value the raw value, possibly {@code null}
374	     * @return the normalized value
375	     */
376	    private String normalizeForHousehold(String value) {
377	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
378	    }
379	
380	    /**
381	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
382	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
383	     * value yields an empty string.
384	     *
385	     * @param value the raw value, possibly {@code null}
386	     * @return the trimmed, whitespace-collapsed value
387	     */
388	    private String collapseWhitespace(String value) {
389	        if (value == null) {
390	            return "";
391	        }
392	        return value.trim().replaceAll("\\s+", " ");
393	    }
394	
395	    /**
396	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
397	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
398	     * is upper-cased, and common street-type abbreviations are expanded as whole words
399	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
400	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
401	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
402	     *
403	     * @param address the raw address value, possibly {@code null}
404	     * @return the normalized address
405	     */
406	    private String normalizeAddress(String address) {
407	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
408	        if (collapsed.isEmpty()) {
409	            return "";
410	        }
411	        String[] tokens = collapsed.split(" ");
412	        StringBuilder normalized = new StringBuilder();
413	        for (int i = 0; i < tokens.length; i++) {
414	            if (i > 0) {
415	                normalized.append(' ');
416	            }
417	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
418	        }
419	        return normalized.toString();
420	    }
421	
422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
425	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
426	        if (currentOwner == null) {
427	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
428	        }
429	        currentOwner.setAddress(ownerFieldsDto.getAddress());
430	        currentOwner.setCity(ownerFieldsDto.getCity());
431	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
432	        currentOwner.setLastName(ownerFieldsDto.getLastName());
433	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
434	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
435	        this.clinicService.saveOwner(currentOwner);
436	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
437	    }
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Transactional
441	    @Override
442	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
443	        Owner owner = this.clinicService.findOwnerById(ownerId);
444	        if (owner == null) {
445	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
446	        }
447	        this.clinicService.deleteOwner(owner);
448	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
449	    }
